import{CONFIG}from"./config.js";class ReadingModeManager{constructor(){this.currentMode=this.loadMode()}init(){this.applyMode(this.currentMode,false);const toggle=document.getElementById("readingModeToggle");if(!CONFIG.showReadingModeToggle&&toggle){toggle.style.display="none";return}const toggleButtons=document.querySelectorAll(".mode-btn");toggleButtons.forEach(btn=>{btn.addEventListener("click",e=>{const mode=e.target.dataset.mode;if(mode!==this.currentMode){this.switchMode(mode)}})});this.updateToggleUI()}loadMode(){return"scroll"}switchMode(newMode){const currentChapter=window.currentChapterId;this.currentMode=newMode;this.applyMode(newMode,true);this.updateToggleUI();if(window.readerInstance&&currentChapter){window.readerInstance.loadChapter(currentChapter,0)}window.dispatchEvent(new CustomEvent("readingModeChanged",{detail:{mode:newMode}}))}applyMode(mode,isSwitch=false){const body=document.body;if(mode==="page"){body.classList.add("paginated");body.classList.remove("scrolling")}else{body.classList.add("scrolling");body.classList.remove("paginated")}}updateToggleUI(){const buttons=document.querySelectorAll(".mode-btn");buttons.forEach(btn=>{if(btn.dataset.mode===this.currentMode){btn.classList.add("active");btn.setAttribute("aria-pressed","true")}else{btn.classList.remove("active");btn.setAttribute("aria-pressed","false")}})}getMode(){return this.currentMode}isPageMode(){return this.currentMode==="page"}isScrollMode(){return this.currentMode==="scroll"}}const readingModeManager=new ReadingModeManager;export{readingModeManager};window.readingModeManager=readingModeManager;